use Kulturhus\Verein\{Database,Finance,OutgoingInvoices,AssetBooks,SettingsSchema,DocumentPreview};
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);if(!Database::tableExists($db,'outgoing_invoices'))throw new RuntimeException('MySQL schema missing outgoing_invoices');
$db->exec("INSERT INTO clubs VALUES('a','Synthetic'),('b','Other');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('admin','a','member',1),('foreign','b','member',1),('member','a','member',0)");$n=0;function ok($v,$l){global $n;if(!$v)throw new RuntimeException($l);++$n;echo "PASS $l\n";}function denied(callable $f,$l){try{$f();}catch(DomainException){ok(true,$l);return;}throw new RuntimeException($l);}
$key=fn()=>bin2hex(random_bytes(16));$f=new Finance($db,'admin');$account=$f->createAccount('Synthetic bank','offline','0','2025-01-01');$f->saveAccountSettings($account,0,false,'18000');ok(!$f->paymentAccounts(),'disabled account absent from new payments');denied(fn()=>$f->requireActiveAccount($account),'disabled account rejected');ok(count($f->accounts())===1,'history still available');denied(fn()=>$f->saveAccountSettings($account,0,true,''),'stale account settings rejected');$f->saveAccountSettings($account,1,true,'18000');ok($f->accounts()[0]['tax_account']==='18000','tax mapping saved permanently');denied(fn()=>$f->createBankTransactionLocked([], $key()),'bank atomic API rejects outside transaction');
foreach(['club'=>['name'=>'Fiktiver Musterverein','street'=>'Musterweg 1','postcode'=>'12345','city'=>'Musterstadt','email'=>'seller@example.org','phone'=>'+49 123 456789','register'=>'VR 12345 Musterstadt'],'tax'=>['number'=>'123/456/78901','depreciation_enabled'=>true],'bank'=>['iban'=>'DE89370400440532013000','holder'=>'Fiktiver Musterverein','account_id'=>$account]] as $section=>$values){$data=array_replace(SettingsSchema::defaults($section),$values);$db->prepare('INSERT INTO club_settings(club_id,section,version,payload,updated_at) VALUES(?,?,1,?,?)')->execute(['a',$section,json_encode($data),gmdate('c')]);}
$service=new OutgoingInvoices($db,'admin');$data=['domestic_confirmed'=>'1','seller_contact'=>'Fiktive Rechnungsstelle','buyer_name'=>'Fiktive Kundin','buyer_street'=>'Testweg 2','buyer_postcode'=>'23456','buyer_city'=>'Beispielstadt','buyer_email'=>'buyer@example.org','buyer_reference'=>'K-100','description'=>'Raumnutzung','note'=>'Vereinbarte Nutzung','vat_reason'=>'','document_date'=>'2025-12-01','delivery_date'=>'2025-12-01','due_date'=>'2025-12-15','category'=>'rooms','contact_id'=>'','payment_account'=>$account,'positions'=>[['description'=>'Raumnutzung','quantity'=>'3','unit'=>'DAY','unit_gross'=>'119','tax_rate'=>'19','sphere'=>'2','account'=>'']]];
$request=$key();$id=$service->save('',0,$data,$request);ok($id===$service->save('',0,$data,$request),'draft duplicate submit idempotent');ok($db->query('SELECT count(*) FROM finance_entries')->fetchColumn()==0,'draft creates no financial entry');ok($service->get($id)['data']['total_cents']===35700,'quantity times gross price');denied(fn()=>(new OutgoingInvoices($db,'foreign'))->get($id),'tenant isolation');denied(fn()=>(new OutgoingInvoices($db,'member'))->save('',0,$data,$key()),'member cannot create invoice');denied(fn()=>$service->save($id,7,$data,$key()),'stale draft preserved');denied(fn()=>$service->issue($id,1),'review required');
$service->review($id,1);ok($service->get($id)['state']==='reviewed','real PDF review succeeds');$entry=$service->issue($id,2);$invoice=$service->get($id);ok($invoice['state']==='issued'&&$invoice['number']!==''&&$invoice['document_id']!==null,'issue linked number ledger and PDF');ok($entry===$service->issue($id,2),'double issue has one entry');denied(fn()=>$service->save($id,3,$data,$key()),'issued draft immutable');$preview=$service->preview($id);ok($preview['positions'][0]['quantity']==='3'&&$preview['positions'][0]['unit']==='Tage','issued snapshot keeps quantity and unit');$service->queue($id,3);$service->queue($id,3);ok($db->query('SELECT COUNT(*) FROM outgoing_invoice_deliveries')->fetchColumn()==1,'mail queue idempotent; no mail sent');
$f->recordPayment($entry,1,$account,'2025-12-02','119');denied(fn()=>$service->correct($id,3,'cancellation','0','Test','2025-12-03',$key()),'paid invoice cannot be silently cancelled');denied(fn()=>$service->correct($id,3,'credit','120','Test','2025-12-03',$key()),'credit cannot exceed actual payment');$credit=$service->correct($id,3,'credit','119','Teil der Leistung entfällt','2025-12-03',$key());ok($service->get($credit)['kind']==='credit'&&$f->entry($service->get($credit)['entry_id'])['payment_state']==='open','credit leaves refund open; no fictional transaction');ok($db->query('SELECT COUNT(*) FROM finance_transactions')->fetchColumn()==1,'credit never sends or records payment');denied(fn()=>$service->correct($id,3,'credit','1','Test','2025-12-03',$key()),'already credited payment excluded');
$second=$service->save('',0,$data,$key());$service->review($second,1);$secondEntry=$service->issue($second,2);$cancel=$service->correct($second,3,'cancellation','0','Leistung entfällt','2025-12-04',$key());ok($f->entry($secondEntry)['status']==='cancelled'&&$service->get($cancel)['number']!==$service->get($second)['number'],'unpaid cancellation has own number and document');
$db->exec("INSERT INTO inventory_items(club_id,id,code,name,kind) VALUES('a','i','INV-1','Fiktives Gerät','reusable'),('b','j','INV-2','Fremdes Gerät','reusable')");$books=new AssetBooks($db,'admin');$plan=['basis'=>'1000','residual'=>'1','acquired_on'=>'2024-10-20','months'=>'36','sphere'=>'3','account'=>'','reason'=>'Lineare Nutzungsdauer fachlich bestätigt; Bruttowert ohne Vorsteuerabzug.'];$books->save('i',0,$plan);$p=$books->get('i')['data'];$a=AssetBooks::schedule($p,2024);ok($a['months']===3&&$a['depreciation_cents']===8325,'first year from acquisition month including October');$total=0;for($y=2024;$y<=2027;$y++)$total+=AssetBooks::schedule($p,$y)['depreciation_cents'];ok($total===99900&&AssetBooks::schedule($p,2027)['closing_cents']===100,'rounded years preserve exact residual');denied(fn()=>$books->recordYear('i',1,2025),'cannot skip first year');$books->recordYear('i',1,2024);$books->recordYear('i',1,2025);denied(fn()=>$books->save('i',1,$plan),'recorded years cannot be silently rewritten');denied(fn()=>$books->recordYear('i',1,2025),'year cannot be recorded twice');denied(fn()=>(new AssetBooks($db,'foreign'))->get('i'),'asset tenant separation');denied(fn()=>(new AssetBooks($db,'member'))->save('i',1,$plan),'asset write permission');ok(count($books->get('i')['history'])===1&&count($books->get('i')['years'])===2,'plan history and year snapshots persist');echo "$n finance workflow checks passed\n";
